CREATE TABLE `avisor_notifications` (
  `notification_id` bigint NOT NULL,
  `user_id` bigint NOT NULL COMMENT 'ไอดีอาจารย์ผู้รับข้อความ',
  `type` enum('info','warning','request','success') DEFAULT 'info',
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `student_id` varchar(50) DEFAULT NULL COMMENT 'รหัสนักศึกษาต้นเหตุ (ถ้ามี)',
  `is_read` tinyint(1) DEFAULT '0' COMMENT '0=ยังไม่อ่าน, 1=อ่านแล้ว',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

